// v24.xx (bigguns3), HIS ORDER (2026-10-12) "guns in player's characters hands need to be bigger/look more impressive": THE SHOT LEAVES
// THE DRAWN MUZZLE. With the big guns the flash, the tracer and the brass still came from the old stub: every shot showed two
// flashes (the old disc at the gun tip and the star at 17 units along the aim, 8 units lower), the tracer started inside the gun
// and the brass popped out of the feet. Each body records where its gun was drawn (GUNMZ, kept beside the body, never on it), and
// gunMuzzle and gunPort give the DRAWN muzzle and ejection port for any aim. The one flash is the star at the drawn muzzle (larger
// on the long guns and the LMG); the old disc is gone. A tracer shows nothing while its round is still inside the drawn gun, starts
// at the muzzle, and eases from the muzzle height down to its old lane over its first 120 units. Brass flies from the ejection
// port. Draw only: every round still spawns 17 units out along the aim with the same range, spread and hit rules, nothing new is
// sent to the party, and the brass keeps its own cosmetic stream (fxn), so the seeded stream is untouched.
var GUNMZ=(typeof WeakMap==='function')?new WeakMap():null;
function gunMzRec(o,px,gy,D,ext){
  var r;
  if(!GUNMZ||!o||typeof o!=='object'||!D) return;
  r=GUNMZ.get(o); if(!r){ r={}; GUNMZ.set(o,r); }
  r.dx=px-(+o.x||0); r.dy=gy-(+o.y||0); r.L=D.tip+ext; r.by=D.by; r.port=D.port[0]+ext;
}
function gunMuzzle(o,a){
  var r=(GUNMZ&&o&&typeof o==='object')?GUNMZ.get(o):null, bf;
  if(!r||!isFinite(o.x)||!isFinite(o.y)||!isFinite(a)) return null;
  bf=r.by*(Math.cos(a)<0?-1:1);
  return {x:o.x+r.dx+Math.cos(a)*r.L-Math.sin(a)*bf, y:o.y+r.dy+Math.sin(a)*r.L+Math.cos(a)*bf, L:r.L};
}
function gunPort(o,a){
  var r=(GUNMZ&&o&&typeof o==='object')?GUNMZ.get(o):null, al=r?r.port:6, sd=(Math.cos(a)<0)?-3:3;
  return {x:o.x+Math.cos(a)*al-Math.sin(a)*sd, y:o.y+Math.sin(a)*al+Math.cos(a)*sd};
}
// the visible streak of a round: [tail x, tail y, head x, head y], or null while it is still inside the drawn gun
function tracerSeg(b,bm,len){
  var ux=b.vx/bm, uy=b.vy/bm, o=b.owner, out=[b.x-ux*len,b.y-uy*len-12,b.x,b.y-12], m, d, td, k, kt, ox, oy;
  if(!o||typeof o!=='object'||!GUNMZ||!GUNMZ.get(o)||!isFinite(o.x)) return out;
  d=(b.x-o.x)*ux+(b.y-o.y)*uy;
  m=gunMuzzle(o,Math.atan2(uy,ux));
  if(!m||d>m.L+120) return out;
  if(d<=m.L) return null;
  ox=m.x-(o.x+ux*m.L); oy=m.y-(o.y+uy*m.L-12);
  td=Math.max(m.L,d-len); k=1-(d-m.L)/120; kt=1-(td-m.L)/120;
  return [b.x-ux*(d-td)+ox*kt, b.y-uy*(d-td)-12+oy*kt, b.x+ox*k, b.y-12+oy*k];
}

